      r'\b(?:wudu|ghusl)\b.*\b(?:make ?up|lipstick|foundation|sunscreen|sunblock|moisturi[sz]er|lotion|cream|henna|mehndi|tattoo|plaster|bandage|cast|sticker|glue|wax|paint)\b',
